// swift-tools-version: 6.2

import PackageDescription

// The Padlok API client, for the apps: add https://github.com/Illumineering/Padlok-Api
// and import PadlokAPIClient.
//
// Only the client lives here, so that an app resolves nothing but swift-openapi-runtime.
// The server is its own package, in Server/. The client is generated from openapi.yaml
// by scripts/generate-client and committed, rather than generated by the build plugin,
// which every app would then have to resolve and build along with its dependencies.
let package = Package(
    name: "PadlokAPI",
    platforms: [.macOS(.v10_15), .macCatalyst(.v13), .iOS(.v13), .tvOS(.v13), .watchOS(.v6), .visionOS(.v1)],
    products: [
        .library(name: "PadlokAPIClient", targets: ["PadlokAPIClient"])
    ],
    dependencies: [
        .package(url: "https://github.com/apple/swift-openapi-runtime.git", from: "1.13.4"),
        // Already a dependency of the runtime: named here because the admin token
        // middleware edits the request's header fields.
        .package(url: "https://github.com/apple/swift-http-types.git", from: "1.8.0"),
    ],
    targets: [
        .target(
            name: "PadlokAPIClient",
            dependencies: [
                .product(name: "OpenAPIRuntime", package: "swift-openapi-runtime"),
                .product(name: "HTTPTypes", package: "swift-http-types"),
            ]
        ),
        .testTarget(
            name: "PadlokAPIClientTests",
            dependencies: ["PadlokAPIClient"]
        ),
    ],
    swiftLanguageModes: [.v6]
)
